const GLOSARIO = [
 ["Acto de alguacil","Documento con el que un alguacil notifica oficialmente una demanda, sentencia, intimación o embargo. Desde ese momento corren los plazos."],
 ["Actor civil","Víctima que se suma al proceso penal para reclamar una indemnización por el daño sufrido."],
 ["Apostilla","Sello que certifica un documento público para que tenga validez en otro país del Convenio de La Haya. En República Dominicana la emite el MIREX."],
 ["Arraigo","Pruebas de que el imputado tiene domicilio, trabajo y familia fijos. Es clave para evitar la prisión preventiva."],
 ["Certificado de título","Documento que prueba la propiedad de un inmueble registrado. Lo emite el Registro de Títulos."],
 ["Cuota litis","Forma de pago en la que el abogado cobra un porcentaje de lo que obtenga para el cliente, generalmente sin pago inicial."],
 ["Deslinde","Proceso técnico y judicial que individualiza una porción dentro de una parcela y le asigna su propia designación catastral."],
 ["Determinación de herederos","Decisión que establece oficialmente quiénes son los herederos de una persona fallecida."],
 ["Estado jurídico","Certificación del Registro de Títulos que indica quién es el dueño de un inmueble y si tiene hipotecas, embargos u oposiciones."],
 ["Exequátur","Autorización del Poder Ejecutivo para ejercer como abogado o notario. También se llama así el procedimiento para ejecutar en el país una sentencia extranjera."],
 ["Homologación","Aprobación judicial de un acuerdo entre las partes, que le da fuerza de sentencia."],
 ["Iguala","Contrato de asesoría legal permanente por una tarifa mensual fija."],
 ["Intimación","Requerimiento formal, casi siempre por acto de alguacil, para que alguien cumpla una obligación en un plazo."],
 ["Litis","Conflicto judicial. Sobre inmuebles registrados se habla de litis sobre derechos registrados."],
 ["Medida de coerción","Medida que dicta el juez para asegurar que el imputado se presente al proceso: desde presentación periódica hasta prisión preventiva."],
 ["Pagaré notarial","Reconocimiento de deuda firmado ante notario que permite embargar directamente si no se paga."],
 ["Partición","División de bienes en común entre herederos, excónyuges o copropietarios."],
 ["Poder especial","Documento por el que una persona autoriza a otra a realizar un acto concreto en su nombre."],
 ["Prescripción","Pérdida del derecho a reclamar por no hacerlo dentro del plazo que fija la ley."],
 ["Prestaciones laborales","Preaviso y auxilio de cesantía que corresponden al trabajador cuando termina el contrato sin causa imputable a él."],
 ["Querella","Escrito con el que la víctima pide al Ministerio Público perseguir un delito y participa como parte en el proceso."],
 ["Saneamiento","Proceso para registrar por primera vez un terreno y obtener su certificado de título."],
 ["Sentencia firme","Sentencia contra la que ya no cabe ningún recurso."],
 ["Laudo arbitral","Decisión final de un tribunal arbitral. Es obligatoria para las partes, como una sentencia."]
];

const FAQ = [
 ["¿Cuánto cuesta la primera consulta?","La consulta inicial cuesta RD$3,500 en la oficina, RD$3,000 por videollamada y RD$2,000 por llamada. Si contrata el servicio, ese monto se descuenta de los honorarios."],
 ["¿Los precios publicados son definitivos?","Son honorarios referenciales para que sepa desde el principio en qué rango está su caso. El monto exacto se fija por escrito después de estudiar sus documentos, antes de empezar."],
 ["¿Qué no incluyen los honorarios?","No incluyen el ITBIS (18 %), impuestos (DGII, transferencia, sucesoral), tasas de instituciones, actos de alguacil, publicaciones, peritos, agrimensores ni traducciones. Se los detallamos aparte, con recibos."],
 ["¿Puedo pagar por partes?","Sí. Puede pagar por etapas del proceso, en cuotas acordadas, por iguala mensual (empresas) o, en casos laborales y de indemnización, con cuota litis: un porcentaje de lo que se obtenga."],
 ["¿Atienden fuera de Santo Domingo?","Sí. Atendemos en todo el país y a dominicanos en el exterior por videollamada. Para audiencias fuera de la ciudad se acuerdan los gastos de traslado."],
 ["¿Qué tan rápido responden?","Respondemos en menos de 24 horas laborables. Las urgencias penales (arrestos, medidas de coerción, hábeas corpus) y de violencia se atienden el mismo día."],
 ["¿Mi información es confidencial?","Sí. Todo lo que nos cuente está protegido por el secreto profesional del abogado, aunque no llegue a contratar el servicio."],
 ["¿Cómo sé en qué va mi caso?","Le enviamos un reporte en cada etapa del proceso y puede escribirnos en cualquier momento. Recibirá copia de cada escrito y sentencia."],
 ["¿Qué pasa si pierdo el caso?","Le explicamos desde el inicio las probabilidades y riesgos reales. En cuota litis, si no se obtiene nada, no paga honorarios (solo gastos acordados)."],
 ["¿Necesito ir en persona?","No siempre. Muchos trámites se hacen con poder especial. Solo se requiere su presencia para firmas ante notario o cuando el juez la exige."]
];

